function solve(s, wordDict) {
  const words = new Set();
  for (const w of wordDict) if (w !== '') words.add(w);
  const n = s.length;
  const res = [];
  function go(i, parts) {
    if (i === n) {
      res.push(parts.join(' '));
      return;
    }
    for (let j = i + 1; j <= n; j++) {
      const w = s.slice(i, j);
      if (words.has(w)) {
        parts.push(w);
        go(j, parts);
        parts.pop();
      }
    }
  }
  go(0, []);
  res.sort();
  return res;
}

function solve(s, wordDict) {
  const words = new Set();
  for (const w of wordDict) if (w !== '') words.add(w);
  const n = s.length;
  const memo = new Map();
  function go(i) {
    if (memo.has(i)) return memo.get(i);
    const out = [];
    if (i === n) {
      out.push('');
    } else {
      for (let j = i + 1; j <= n; j++) {
        const w = s.slice(i, j);
        if (words.has(w)) {
          for (const tail of go(j)) {
            out.push(tail === '' ? w : w + ' ' + tail);
          }
        }
      }
    }
    memo.set(i, out);
    return out;
  }
  const res = go(0);
  res.sort();
  return res;
}
